804:      ledger({ item: item.id, text_hash: item.text_hash, run: batch.run, status: 'error', error_kind: kind, attempt: 2, cost_usd: share });
810:    for (const item of batch.items) ledger({ item: item.id, text_hash: item.text_hash, run: batch.run, status: 'stopped', error_kind: kind });
841:  io.out(`judge: items=${opts.items} runs=${runs} model=${model} config=${config16} cells=${totalCells} done=${counts.done} skipped=${counts.skipped} error=${counts.error} stopped=${counts.stopped} cost=$${round(cost, 4)} status=${status}${opts.smoke ? ' smoke=yes' : ''} run=${runId}`);
854:    io.err(`judge: ${errorCells} of ${totalCells} item runs failed (${(errorShare * 100).toFixed(1)}%; the limit is ${(S.maxErrorShare * 100).toFixed(0)}%). They are in the ledger with status error and the next run tries them again.`);

